// Some portions generated by Claude
import { useMemo, useState, type Ref } from "react";
import type { ContextMenu, PredicateOption } from "./explorer-types.ts";
import { compactTerm } from "./graph-terms.ts";
import { Icon } from "./icons.tsx";
import { relationLimits, type RelationAmount } from "./relation-expansion.ts";

export type NodeMenuProps = {
  menu: ContextMenu;
  closing: boolean;
  menuRef: Ref<HTMLElement>;
  canGroup: boolean;
  canHideLeaves: boolean;
  onDismiss: () => void;
  onExpandAll: () => void;
  onShowDetails: () => void;
  onLoadRelations: () => void;
  onExpandRelation: (option: PredicateOption) => void;
  /** The amount chosen for a relation with more new links than load at once (phase "confirm"). */
  onLoadRelation: (amount: RelationAmount) => void;
  onCancelRelation: () => void;
  onSelectNeighbours: (mode: "replace" | "extend" | "invert") => void;
  onGroup: () => void;
  onHideLeaves: () => void;
  onHide: () => void;
};

/** The right-click (long-press) menu of a node or of the selection it belongs to. */
export function NodeMenu({
  menu,
  closing,
  menuRef,
  canGroup,
  canHideLeaves,
  onDismiss,
  onExpandAll,
  onShowDetails,
  onLoadRelations,
  onExpandRelation,
  onLoadRelation,
  onCancelRelation,
  onSelectNeighbours,
  onGroup,
  onHideLeaves,
  onHide,
}: NodeMenuProps) {
  const [predicateSearch, setPredicateSearch] = useState("");
  const relations = useMemo(() => {
    const searchTerm = predicateSearch.trim().toLocaleLowerCase();
    if (!searchTerm) return menu.predicates;
    return menu.predicates.filter((option) =>
      [option.label, compactTerm(option.predicate, 48), option.predicate, option.direction].some((value) =>
        value.toLocaleLowerCase().includes(searchTerm),
      ),
    );
  }, [menu.predicates, predicateSearch]);
  return (
    <>
      <button
        className={`context-scrim${closing ? " is-closing" : ""}`}
        type="button"
        aria-label="Close node actions"
        onClick={() => onDismiss()}
        onWheel={() => onDismiss()}
      />
      <section
        ref={menuRef}
        className={`predicate-menu${closing ? " is-closing" : ""}`}
        role="dialog"
        aria-label={`Actions for ${menu.node.label}`}
        aria-live="polite"
        tabIndex={-1}
        style={{
          left:
            typeof window === "undefined"
              ? Math.max(12, menu.x + 10)
              : Math.max(
                  12,
                  Math.min(menu.x + 10, window.innerWidth - 372),
                ),
          top:
            typeof window === "undefined"
              ? Math.max(12, menu.y + 10)
              : Math.max(
                  12,
                  Math.min(menu.y + 10, window.innerHeight - 602),
                ),
        }}
        onClick={(event) => event.stopPropagation()}
        onPointerDown={(event) => event.stopPropagation()}
        onKeyDown={(event) => {
          if (event.key === "Escape") {
            event.stopPropagation();
            onDismiss();
          }
        }}
      >
        <div className="menu-header">
          <h3>
            {menu.scopeNodeIds.length > 1
              ? `${menu.scopeNodeIds.length} selected nodes`
              : menu.node.label}
          </h3>
          <button
            className="workbench-action workbench-action--ghost workbench-action--icon"
            type="button"
            aria-label="Close node actions"
            title="Close node actions"
            onClick={() => onDismiss()}
          >
            <Icon name="close" />
          </button>
        </div>

        <div className="context-menu-body">
          <div className="context-actions">
            {menu.nodeIds.length ? (
              <button
                type="button"
                className="is-primary"
                onClick={onExpandAll}
              >
                <Icon name="expand" />
                <strong>Expand</strong>
              </button>
            ) : null}
            {menu.scopeNodeIds.length === 1 ? (
              <button
                type="button"
                onClick={() => {
                  onShowDetails();
                }}
              >
                <Icon name="inspect" />
                <strong>Details</strong>
              </button>
            ) : null}
          </div>
          <details
            className="context-disclosure"
            onToggle={(event) => {
              if (event.currentTarget.open && menu.phase === "idle") {
                onLoadRelations();
              }
            }}
          >
            <summary>
              <span>
                <strong>Expand by relation</strong>
              </span>
              <svg
                viewBox="0 0 16 16"
                aria-hidden="true"
                focusable="false"
              >
                <path d="M4 6l4 4 4-4" />
              </svg>
            </summary>
            <div className="disclosure-content">
              {menu.phase === "loading" && (
                <p className="menu-message menu-loading">
                  {menu.message ?? "Looking up relations…"}
                </p>
              )}
              {menu.phase === "confirm" && menu.relation && (
                <RelationAmountForm
                  relation={menu.relation}
                  selected={menu.nodeIds.length}
                  onLoad={onLoadRelation}
                  onCancel={onCancelRelation}
                />
              )}
              {menu.phase === "error" && (
                <div className="menu-error-block">
                  <p className="menu-error">{menu.error}</p>
                  {menu.nodeIds.length > 0 && (
                    <button
                      className="workbench-action workbench-action--secondary"
                      type="button"
                      onClick={onLoadRelations}
                    >
                      Try again
                    </button>
                  )}
                </div>
              )}
              {menu.phase === "ready" && (
                <>
                  {menu.predicates.length > 0 && (
                    <label className="predicate-search">
                      <span className="workbench-visually-hidden">Search relations</span>
                      <input
                        type="search"
                        value={predicateSearch}
                        placeholder="Search relations"
                        autoComplete="off"
                        onChange={(event) =>
                          setPredicateSearch(event.target.value)
                        }
                      />
                    </label>
                  )}
                  <div className="predicate-list">
                    {relations.length ? (
                      relations.map((option) => (
                        <button
                          key={`${option.direction}-${option.predicate}`}
                          type="button"
                          onClick={() => onExpandRelation(option)}
                        >
                          <span
                            className={`direction ${option.direction}`}
                            title={option.direction === "outgoing" ? "Outgoing: links from this node" : "Incoming: links to this node"}
                          >
                            {option.direction === "outgoing"
                              ? "OUT"
                              : "IN"}
                          </span>
                          <span className="predicate-label">
                            {option.label}
                          </span>
                          {option.count !== null && (
                            <span
                              className="predicate-count"
                              title={`${option.count.toLocaleString()} of the ${menu.nodeIds.length} selected nodes have this relation`}
                            >
                              {option.count.toLocaleString()}/
                              {menu.nodeIds.length}
                            </span>
                          )}
                        </button>
                      ))
                    ) : menu.predicates.length ? (
                      <p className="menu-message">
                        Nothing matches “{predicateSearch.trim()}”.
                      </p>
                    ) : (
                      <p className="menu-message">
                        No relations found.
                      </p>
                    )}
                  </div>
                </>
              )}
            </div>
          </details>

          <div className="context-actions">
            <button
              type="button"
              onClick={() => onSelectNeighbours("replace")}
            >
              <strong>Select neighbours</strong>
            </button>
            <button
              type="button"
              onClick={() => onSelectNeighbours("extend")}
            >
              <strong>Add neighbours to selection</strong>
            </button>
            <button
              type="button"
              onClick={() => onSelectNeighbours("invert")}
            >
              <strong>Invert selection</strong>
            </button>
            {canGroup ? (
              <button type="button" onClick={onGroup}>
                <strong>Save selection as a group…</strong>
              </button>
            ) : null}
            {canHideLeaves ? (
              <button
                type="button"
                onClick={() => {
                  onHideLeaves();
                }}
              >
                <strong>Hide neighbours with no other links</strong>
              </button>
            ) : null}
          </div>
          <div className="context-actions">
            <button
              type="button"
              className="is-danger"
              onClick={onHide}
              title="Hide (Delete). Undo brings it back."
            >
              <Icon name="hide" />
              <strong>
                {menu.scopeNodeIds.length > 1 ? `Hide ${menu.scopeNodeIds.length} nodes` : "Hide"}
              </strong>
            </button>
          </div>
        </div>
      </section>
    </>
  );
}

/**
 * How many of a relation's new links to load, in total (shared evenly across the nodes) or per node, when there are
 * more than load at once. It starts at all of them.
 */
function RelationAmountForm({
  relation,
  selected,
  onLoad,
  onCancel,
}: {
  relation: NonNullable<ContextMenu["relation"]>;
  selected: number;
  onLoad: (amount: RelationAmount) => void;
  onCancel: () => void;
}) {
  const nodes = relation.available.size;
  const [mode, setMode] = useState<RelationAmount["mode"]>("total");
  const [amounts, setAmounts] = useState(() => ({
    total: String(relation.total),
    perNode: String(Math.max(...relation.available.values())),
  }));
  const amount = Number(amounts[mode]);
  const limits = relationLimits(relation.available, { mode, amount }, relation.capped);
  const loads = [...limits.values()].reduce((sum, links) => sum + links, 0);
  const label = relation.option.label;
  const holders =
    selected === 1
      ? "This node has"
      : nodes === selected
        ? `The ${selected.toLocaleString()} selected nodes have`
        : `${nodes.toLocaleString()} of the ${selected.toLocaleString()} selected nodes have`;
  return (
    <form
      className="relation-amount"
      aria-label={`How many ${label} links to load`}
      onSubmit={(event) => {
        event.preventDefault();
        if (loads) onLoad({ mode, amount });
      }}
    >
      <p className="menu-message">
        {holders} {relation.atLeast ? "at least " : ""}
        {relation.total.toLocaleString()} {label} links that are not in the graph yet. How many should be loaded?
      </p>
      {nodes > 1 && (
        <div className="relation-amount__modes" role="radiogroup" aria-label="Count the links">
          <label>
            <input type="radio" name="relation-amount-mode" checked={mode === "total"} onChange={() => setMode("total")} />
            In total
          </label>
          <label>
            <input type="radio" name="relation-amount-mode" checked={mode === "perNode"} onChange={() => setMode("perNode")} />
            Per node
          </label>
        </div>
      )}
      <label className="relation-amount__count">
        <span>{mode === "total" ? "Links in total" : "Links per node"}</span>
        <input
          type="number"
          inputMode="numeric"
          min={1}
          step={1}
          value={amounts[mode]}
          autoFocus
          onChange={(event) => {
            const value = event.target.value;
            setAmounts((current) => ({ ...current, [mode]: value }));
          }}
        />
      </label>
      <p className="menu-message relation-amount__summary" aria-live="polite">
        {loads
          ? `Loads ${relation.atLeast ? "up to " : ""}${loads.toLocaleString()} ${loads === 1 ? "link" : "links"}${
              nodes > 1 ? ` from ${limits.size.toLocaleString()} ${limits.size === 1 ? "node" : "nodes"}` : ""
            }.`
          : "Choose at least one link."}
      </p>
      <div className="relation-amount__actions">
        <button className="workbench-action workbench-action--primary" type="submit" disabled={!loads}>
          Load {loads ? loads.toLocaleString() : ""}
        </button>
        <button className="workbench-action workbench-action--secondary" type="button" onClick={onCancel}>
          Cancel
        </button>
      </div>
    </form>
  );
}
